const CATEGORY_MAP = {
  expense: ["餐饮", "交通", "购物", "居住", "娱乐", "医疗", "教育", "其他支出"],
  income: ["工资", "奖金", "兼职", "投资", "红包", "其他收入"]
};

const TYPE_LABEL = { income: "收入", expense: "支出" };

const state = {
  records: [],
  filterMonth: "all",
  pendingDeleteId: null
};

const el = {
  form: null,
  date: null,
  typeInputs: [],
  category: null,
  amount: null,
  note: null,
  formError: null,
  resetBtn: null,
  monthSelect: null,
  list: null,
  emptyState: null,
  listSummary: null,
  statIncome: null,
  statExpense: null,
  statBalance: null,
  statIncomeCount: null,
  statExpenseCount: null,
  statBalanceHint: null,
  balanceCard: null,
  backdrop: null,
  dialogText: null,
  dialogConfirm: null,
  dialogCancel: null
};

function pad2(n) {
  return String(n).padStart(2, "0");
}

function todayISO() {
  const d = new Date();
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

function formatMoney(value) {
  const num = Number(value);
  const safe = Number.isFinite(num) ? num : 0;
  const sign = safe < 0 ? "-" : "";
  return `${sign}¥${Math.abs(safe).toFixed(2)}`;
}

function monthOf(dateStr) {
  if (typeof dateStr !== "string" || dateStr.length < 7) return "";
  return dateStr.slice(0, 7);
}

function monthLabel(month) {
  if (!month) return "未知月份";
  const parts = month.split("-");
  if (parts.length < 2) return month;
  return `${parts[0]} 年 ${Number(parts[1])} 月`;
}

function normalizeRecord(raw) {
  const rec = raw && typeof raw === "object" ? raw : {};
  const type = rec.type === "income" ? "income" : "expense";
  const amountNum = Number(rec.amount);
  return {
    ...rec,
    id: typeof rec.id === "string" && rec.id ? rec.id : `rec_${Math.random().toString(36).slice(2, 10)}`,
    date: typeof rec.date === "string" && rec.date ? rec.date : todayISO(),
    type,
    category: typeof rec.category === "string" && rec.category ? rec.category : CATEGORY_MAP[type][0],
    amount: Number.isFinite(amountNum) ? amountNum : 0,
    note: typeof rec.note === "string" ? rec.note : ""
  };
}

function getSelectedType() {
  const checked = el.typeInputs.find((input) => input.checked);
  return checked && checked.value === "income" ? "income" : "expense";
}

function renderCategoryOptions(type, keepValue) {
  const list = CATEGORY_MAP[type] || CATEGORY_MAP.expense;
  const previous = typeof keepValue === "string" ? keepValue : el.category.value;
  el.category.textContent = "";
  list.forEach((name) => {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    el.category.appendChild(option);
  });
  if (previous && list.includes(previous)) {
    el.category.value = previous;
  } else {
    el.category.value = list[0];
  }
}

function showFormError(message) {
  if (!message) {
    el.formError.hidden = true;
    el.formError.textContent = "";
    return;
  }
  el.formError.textContent = message;
  el.formError.hidden = false;
}

function getFilteredRecords() {
  const sorted = state.records.slice().sort((a, b) => {
    if (a.date === b.date) return 0;
    return a.date < b.date ? 1 : -1;
  });
  if (state.filterMonth === "all") return sorted;
  return sorted.filter((rec) => monthOf(rec.date) === state.filterMonth);
}

function computeTotals(records) {
  let income = 0;
  let expense = 0;
  let incomeCount = 0;
  let expenseCount = 0;
  records.forEach((rec) => {
    const amount = Number(rec.amount);
    const safe = Number.isFinite(amount) ? amount : 0;
    if (rec.type === "income") {
      income += safe;
      incomeCount += 1;
    } else {
      expense += safe;
      expenseCount += 1;
    }
  });
  return { income, expense, balance: income - expense, incomeCount, expenseCount };
}

function renderMonthOptions() {
  const months = Array.from(new Set(state.records.map((rec) => monthOf(rec.date)).filter(Boolean)));
  months.sort((a, b) => (a < b ? 1 : -1));

  if (state.filterMonth !== "all" && !months.includes(state.filterMonth)) {
    state.filterMonth = "all";
  }

  el.monthSelect.textContent = "";
  const allOption = document.createElement("option");
  allOption.value = "all";
  allOption.textContent = "全部月份";
  el.monthSelect.appendChild(allOption);

  months.forEach((month) => {
    const option = document.createElement("option");
    option.value = month;
    option.textContent = monthLabel(month);
    el.monthSelect.appendChild(option);
  });

  el.monthSelect.value = state.filterMonth;
}

function renderStats(records) {
  const totals = computeTotals(records);
  el.statIncome.textContent = formatMoney(totals.income);
  el.statExpense.textContent = formatMoney(totals.expense);
  el.statBalance.textContent = formatMoney(totals.balance);
  el.statIncomeCount.textContent = `${totals.incomeCount} 笔`;
  el.statExpenseCount.textContent = `${totals.expenseCount} 笔`;
  el.statBalanceHint.textContent = `收入 ${totals.incomeCount} 笔 − 支出 ${totals.expenseCount} 笔`;
  el.balanceCard.classList.toggle("is-negative", totals.balance < 0);
}

function buildRecordItem(rec) {
  const li = document.createElement("li");
  li.className = "record-item";
  li.dataset.recordId = rec.id;

  const main = document.createElement("div");
  main.className = "record-main";

  const top = document.createElement("div");
  top.className = "record-top";

  const dateSpan = document.createElement("span");
  dateSpan.className = "record-date";
  dateSpan.textContent = rec.date;
  top.appendChild(dateSpan);

  const typeTag = document.createElement("span");
  typeTag.className = `tag ${rec.type === "income" ? "tag-income" : "tag-expense"}`;
  typeTag.textContent = TYPE_LABEL[rec.type];
  top.appendChild(typeTag);

  const catTag = document.createElement("span");
  catTag.className = "tag tag-category";
  catTag.textContent = rec.category;
  top.appendChild(catTag);

  main.appendChild(top);

  if (rec.note) {
    const note = document.createElement("span");
    note.className = "record-note";
    note.textContent = rec.note;
    main.appendChild(note);
  }

  li.appendChild(main);

  const amount = document.createElement("span");
  amount.className = `record-amount ${rec.type === "income" ? "is-income" : "is-expense"}`;
  amount.textContent = `${rec.type === "income" ? "+" : "−"}${formatMoney(rec.amount)}`;
  li.appendChild(amount);

  const delBtn = document.createElement("button");
  delBtn.type = "button";
  delBtn.className = "record-delete";
  delBtn.dataset.action = "delete";
  delBtn.dataset.recordId = rec.id;
  delBtn.textContent = "删除";
  li.appendChild(delBtn);

  return li;
}

function renderList() {
  const records = getFilteredRecords();
  el.list.textContent = "";

  records.forEach((rec) => {
    el.list.appendChild(buildRecordItem(rec));
  });

  const totals = computeTotals(records);
  const scopeText = state.filterMonth === "all" ? "全部月份" : monthLabel(state.filterMonth);

  if (state.records.length === 0) {
    el.emptyState.hidden = false;
    el.emptyState.textContent = "还没有任何记录，先在左侧添加第一笔吧。";
    el.listSummary.textContent = "暂无记录";
  } else if (records.length === 0) {
    el.emptyState.hidden = false;
    el.emptyState.textContent = "该月份下没有记录，可切换月份或新增一笔。";
    el.listSummary.textContent = `${scopeText}：共 0 笔`;
  } else {
    el.emptyState.hidden = true;
    el.listSummary.textContent = `${scopeText}：共 ${records.length} 笔 · 收入 ${formatMoney(totals.income)} · 支出 ${formatMoney(totals.expense)} · 结余 ${formatMoney(totals.balance)}`;
  }

  renderStats(records);
}

function renderAll() {
  renderMonthOptions();
  renderList();
}

async function persist(nextRecords) {
  const current = await appStore.getState();
  const base = current && typeof current === "object" ? current : {};
  const next = { ...base, records: nextRecords };
  await appStore.setState(next);
  state.records = nextRecords.map(normalizeRecord);
}

function openDeleteDialog(recordId) {
  const rec = state.records.find((item) => item.id === recordId);
  if (!rec) return;
  state.pendingDeleteId = recordId;
  el.dialogText.textContent = `确定删除 ${rec.date} 的${TYPE_LABEL[rec.type]}记录「${rec.category} ${formatMoney(rec.amount)}」吗？此操作不可撤销。`;
  el.backdrop.hidden = false;
  el.dialogConfirm.focus();
}

function closeDeleteDialog() {
  state.pendingDeleteId = null;
  el.backdrop.hidden = true;
}

async function confirmDelete() {
  const id = state.pendingDeleteId;
  if (!id) {
    closeDeleteDialog();
    return;
  }
  const nextRecords = state.records.filter((rec) => rec.id !== id);
  try {
    await persist(nextRecords);
    closeDeleteDialog();
    renderAll();
  } catch (err) {
    el.dialogText.textContent = `删除失败：${err && err.message ? err.message : "存储不可用"}，记录已保留。`;
  }
}

async function handleSubmit(event) {
  event.preventDefault();
  showFormError("");

  const date = el.date.value;
  const type = getSelectedType();
  const category = el.category.value;
  const amountRaw = el.amount.value.trim();
  const note = el.note.value.trim();

  if (!date) {
    showFormError("请选择日期。");
    el.date.focus();
    return;
  }

  const amount = Number(amountRaw);
  if (!amountRaw || !Number.isFinite(amount)) {
    showFormError("请输入有效的金额数字。");
    el.amount.focus();
    return;
  }
  if (amount <= 0) {
    showFormError("金额必须大于 0。");
    el.amount.focus();
    return;
  }
  if (!category) {
    showFormError("请选择分类。");
    el.category.focus();
    return;
  }

  const record = normalizeRecord({
    id: `rec_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`,
    date,
    type,
    category,
    amount: Math.round(amount * 100) / 100,
    note
  });

  const nextRecords = state.records.concat([record]);

  try {
    await persist(nextRecords);
  } catch (err) {
    showFormError(`保存失败：${err && err.message ? err.message : "存储不可用"}，请重试。`);
    return;
  }

  el.amount.value = "";
  el.note.value = "";
  showFormError("");
  renderAll();
  el.amount.focus();
}

function resetForm() {
  el.date.value = todayISO();
  const expenseRadio = el.typeInputs.find((input) => input.value === "expense");
  if (expenseRadio) expenseRadio.checked = true;
  renderCategoryOptions("expense");
  el.amount.value = "";
  el.note.value = "";
  showFormError("");
}

function bindEvents() {
  el.form.addEventListener("submit", handleSubmit);

  el.resetBtn.addEventListener("click", () => {
    resetForm();
    el.date.focus();
  });

  el.typeInputs.forEach((input) => {
    input.addEventListener("change", () => {
      renderCategoryOptions(getSelectedType());
    });
  });

  el.monthSelect.addEventListener("change", () => {
    state.filterMonth = el.monthSelect.value || "all";
    renderList();
  });

  el.list.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLElement)) return;
    const btn = target.closest('[data-action="delete"]');
    if (!btn) return;
    const recordId = btn.dataset.recordId;
    if (recordId) openDeleteDialog(recordId);
  });

  el.dialogCancel.addEventListener("click", closeDeleteDialog);
  el.dialogConfirm.addEventListener("click", confirmDelete);

  el.backdrop.addEventListener("click", (event) => {
    if (event.target === el.backdrop) closeDeleteDialog();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !el.backdrop.hidden) closeDeleteDialog();
  });
}

async function init() {
  el.form = document.querySelector('[data-role="entry-form"]');
  el.date = document.querySelector('[data-role="input-date"]');
  el.typeInputs = Array.from(document.querySelectorAll('[data-role="input-type"]'));
  el.category = document.querySelector('[data-role="input-category"]');
  el.amount = document.querySelector('[data-role="input-amount"]');
  el.note = document.querySelector('[data-role="input-note"]');
  el.formError = document.querySelector('[data-role="form-error"]');
  el.resetBtn = document.querySelector('[data-role="reset-btn"]');
  el.monthSelect = document.querySelector('[data-role="input-month"]');
  el.list = document.querySelector('[data-role="record-list"]');
  el.emptyState = document.querySelector('[data-role="empty-state"]');
  el.listSummary = document.querySelector('[data-role="list-summary"]');
  el.statIncome = document.querySelector('[data-role="stat-income"]');
  el.statExpense = document.querySelector('[data-role="stat-expense"]');
  el.statBalance = document.querySelector('[data-role="stat-balance"]');
  el.statIncomeCount = document.querySelector('[data-role="stat-income-count"]');
  el.statExpenseCount = document.querySelector('[data-role="stat-expense-count"]');
  el.statBalanceHint = document.querySelector('[data-role="stat-balance-hint"]');
  el.balanceCard = el.statBalance.closest(".stat-card");
  el.backdrop = document.querySelector('[data-role="dialog-backdrop"]');
  el.dialogText = document.querySelector('[data-role="dialog-text"]');
  el.dialogConfirm = document.querySelector('[data-role="dialog-confirm"]');
  el.dialogCancel = document.querySelector('[data-role="dialog-cancel"]');

  const stored = await appStore.getState();
  const base = stored && typeof stored === "object" ? stored : {};

  if (!Array.isArray(base.records)) {
    state.records = [];
    try {
      await appStore.setState({ ...base, records: [] });
    } catch (err) {
      showFormError(`初始化存储失败：${err && err.message ? err.message : "存储不可用"}`);
    }
  } else {
    state.records = base.records.map(normalizeRecord);
  }

  state.filterMonth = "all";
  resetForm();
  bindEvents();
  renderAll();
}

await init();

