:root {
  --bg-deep: #0f172a;
  --bg-mid: #16233c;
  --surface: #1e2b45;
  --surface-soft: #24334f;
  --border: #33456a;
  --text: #eef3fb;
  --text-muted: #9fb0cc;
  --accent: #4f8cff;
  --accent-strong: #2f6fe4;
  --income: #34d399;
  --expense: #fb7185;
  --danger: #e11d48;
  --radius: 14px;
  --shadow: 0 18px 40px rgba(6, 12, 26, 0.45);
}

#app {
  min-height: 100vh;
  background: radial-gradient(circle at 12% 0%, #1d2f52 0%, var(--bg-deep) 55%, #0a1120 100%);
  color: var(--text);
  font-family: "PingFang SC", "Microsoft YaHei", "Hiragino Sans GB", system-ui, -apple-system, sans-serif;
  font-size: 15px;
  line-height: 1.55;
  padding: 28px 20px 56px;
  box-sizing: border-box;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 1080px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  font-weight: 700;
  color: #fff;
  background: linear-gradient(140deg, var(--accent) 0%, #7c5cff 100%);
  box-shadow: var(--shadow);
}

.brand-text h1 {
  margin: 0;
  font-size: 22px;
  letter-spacing: 0.5px;
}

.brand-sub {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 13px;
}

.stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.stat-card {
  background: linear-gradient(160deg, var(--surface) 0%, var(--surface-soft) 100%);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  box-shadow: var(--shadow);
}

.stat-label {
  font-size: 13px;
  color: var(--text-muted);
}

.stat-value {
  font-size: 24px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  word-break: break-all;
}

.stat-hint {
  font-size: 12px;
  color: var(--text-muted);
}

.stat-income .stat-value { color: var(--income); }
.stat-expense .stat-value { color: var(--expense); }
.stat-balance .stat-value { color: var(--text); }
.stat-balance.is-negative .stat-value { color: var(--expense); }

.layout {
  display: grid;
  grid-template-columns: minmax(0, 360px) minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 18px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 14px;
  font-size: 16px;
  font-weight: 600;
}

.entry-form {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  border: 0;
  padding: 0;
  margin: 0;
  min-width: 0;
}

.field label,
.field legend {
  font-size: 13px;
  color: var(--text-muted);
  padding: 0;
}

.field input[type="date"],
.field input[type="number"],
.field input[type="text"],
.field select {
  width: 100%;
  padding: 10px 12px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #131e33;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field input::placeholder {
  color: #6d7f9d;
}

.field input:focus,
.field select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 140, 255, 0.22);
}

.field select option {
  background: #131e33;
  color: var(--text);
}

.type-options {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.type-option {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #131e33;
  cursor: pointer;
  font-size: 14px;
  color: var(--text-muted);
  transition: border-color 0.15s ease, color 0.15s ease, background 0.15s ease;
}

.type-option input {
  accent-color: var(--accent);
}

.type-option:has(input:checked) {
  border-color: var(--accent);
  background: rgba(79, 140, 255, 0.16);
  color: var(--text);
}

.form-error {
  margin: 0;
  padding: 9px 12px;
  border-radius: 10px;
  background: rgba(225, 29, 72, 0.16);
  border: 1px solid rgba(225, 29, 72, 0.5);
  color: #ffc2cf;
  font-size: 13px;
}

.form-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.btn {
  border: 1px solid transparent;
  border-radius: 10px;
  padding: 10px 16px;
  font-size: 14px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.08s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: linear-gradient(140deg, var(--accent) 0%, var(--accent-strong) 100%);
  color: #fff;
  font-weight: 600;
  flex: 1 1 auto;
}

.btn-primary:hover {
  background: linear-gradient(140deg, #5f99ff 0%, #3a79ee 100%);
}

.btn-ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text-muted);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--accent);
}

.btn-danger {
  background: var(--danger);
  color: #fff;
  font-weight: 600;
}

.btn-danger:hover {
  background: #f43f5e;
}

.list-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.list-head .panel-title {
  margin: 0;
}

.filter {
  display: flex;
  align-items: center;
  gap: 8px;
}

.filter label {
  font-size: 13px;
  color: var(--text-muted);
  white-space: nowrap;
}

.filter select {
  padding: 8px 10px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #131e33;
  color: var(--text);
  font-size: 14px;
  font-family: inherit;
  outline: none;
}

.filter select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(79, 140, 255, 0.22);
}

.list-summary {
  margin: 0 0 12px;
  font-size: 13px;
  color: var(--text-muted);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 520px;
  overflow-y: auto;
}

.record-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--border);
  background: var(--surface-soft);
}

.record-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.record-top {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.record-date {
  font-size: 13px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.tag {
  font-size: 12px;
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid transparent;
}

.tag-income {
  color: var(--income);
  background: rgba(52, 211, 153, 0.14);
  border-color: rgba(52, 211, 153, 0.4);
}

.tag-expense {
  color: var(--expense);
  background: rgba(251, 113, 133, 0.14);
  border-color: rgba(251, 113, 133, 0.4);
}

.tag-category {
  color: var(--text-muted);
  background: rgba(159, 176, 204, 0.12);
  border-color: var(--border);
}

.record-note {
  font-size: 13px;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.record-amount {
  font-size: 17px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.record-amount.is-income { color: var(--income); }
.record-amount.is-expense { color: var(--expense); }

.record-delete {
  border: 1px solid var(--border);
  background: transparent;
  color: var(--text-muted);
  border-radius: 9px;
  padding: 7px 12px;
  font-size: 13px;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
}

.record-delete:hover {
  color: #fff;
  border-color: var(--danger);
  background: rgba(225, 29, 72, 0.22);
}

.empty-state {
  margin: 0;
  padding: 26px 12px;
  text-align: center;
  color: var(--text-muted);
  font-size: 14px;
  border: 1px dashed var(--border);
  border-radius: 12px;
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(6, 11, 22, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-muted);
  overflow-wrap: anywhere;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 860px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .stats {
    grid-template-columns: minmax(0, 1fr);
  }

  .record-list {
    max-height: none;
  }
}
